INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 26, 'theory', 'Quiz: The Network in the Browser');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 0, 'When does the fetch promise reject?', '["On any 4xx and 5xx response code", "Only on a network error — a 404 or 500 response counts as successfully received", "Only on code 500", "Never"]', 1, 'You check the success of a response yourself, via res.ok or res.status.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 1, 'What happens if you call res.json() twice on the same response?', '["The same result is returned", "The request is repeated", "The body becomes an empty string", "The second call throws an error — the body is read once; make a copy with clone()"]', 3, 'The body is a stream that can be read only once.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 2, 'How do you cancel a fetch request?', '["Pass the signal from an AbortController and call abort()", "res.stop()", "Close the tab", "Call clearTimeout"]', 0, 'The promise rejects with an AbortError; for a timeout there is AbortSignal.timeout(ms).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 3, 'Why does the browser send a preflight OPTIONS request?', '["To check the network speed", "To load the cache", "To ask the server whether the method and headers of a cross-origin request are allowed, before sending the real one", "To compress the body"]', 2, 'Simple requests go out at once, while non-simple ones (for example, with JSON and custom headers) require a preliminary check.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 26, 4, 'How does WebSocket differ from Server-Sent Events?', '["WebSocket is one-way, SSE is two-way", "They are the same", "SSE works only over UDP", "WebSocket is two-way and does not reconnect by itself, SSE is one-way (server → client) and reconnects automatically"]', 3, 'SSE is an ordinary HTTP text stream with automatic Last-Event-ID; WebSocket is a separate protocol after Upgrade.');
